import{z as B,x as A,o as t,c as p,q as r,j as s,D as E,d as n,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"QUEST KV","description":"","frontmatter":{"title":"QUEST KV","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/quest-kv.md","filePath":"llm/quest-kv.md","lastUpdated":1791413859000}'),d={name:"llm/quest-kv.md"};function m(h,a,T,K,_,S){const o=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="quest-kv" tabindex="-1">QUEST KV <a class="header-anchor" href="#quest-kv" aria-label="Permalink to &quot;QUEST KV&quot;">​</a></h1><div class="epigraph"><p>哪些键真正重要，强烈依赖于当前这条查询；与其按历史分数永久扔掉 KV，不如保留全部缓存，每步只把估计最关键的页加载进注意力。</p><footer>—— Tang, Zhao, Zhu, Xiao, Kasikci, Han，QUEST，ICML 2024</footer></div><p><a href="/llm/h2o-kv">H2O</a> 与 <a href="/llm/scissorhands">Scissorhands</a> 用历史注意力做<strong>永久驱逐</strong>。Tang、Zhao、Song Han 等人指出：同一位置对查询 A 无用，对查询 B 可能极关键——论文里用「A is B. C is D. A is」一类例子说明，「is」会回头打到「B」，而中间的「D」不会。QUEST（Query-Aware Sparsity）因此不删 KV，而是<strong>按当前 \\(q\\) 挑选要读的页</strong>。长上下文 decode 的瓶颈是从 HBM 搬完整缓存；只搬 Top-\\(K\\) 页就能降延迟。本篇写页级 min/max 估计与和驱逐算法的分界。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>长窗口（32K、128K）下，decode 每步都要把全部 \\(K,V\\) 读进核。Llama 7B、32K、FP16 的 KV 约 16GB 量级，论文测过读缓存可占单步一半以上时间。已知注意力稀疏——少数 token 主导输出——但「哪少数」随 \\(q\\) 变。历史分数驱逐一旦把将来要用的证据丢掉，针检索、多跳、先叙事后提问都会坏。TOVA 一类「只看当前 \\(q\\) 就永久丢」同样不可逆。</p><p>保留全部 KV 则空间不降，只降逐步带宽。这与分页注意力的物理布局吻合：缓存本来就按页存。QUEST 的问题收成：如何用远小于一页 KV 的元数据，估计「这一页对当前 \\(q\\) 有多可能含高分键」，使得 Top-\\(K\\) 页的近似注意力在长依赖任务上仍可用。</p><h3 id="查询无关稀疏的失败模式" tabindex="-1">查询无关稀疏的失败模式 <a class="header-anchor" href="#查询无关稀疏的失败模式" aria-label="Permalink to &quot;查询无关稀疏的失败模式&quot;">​</a></h3><p>H2O 留下的 H2 是对<strong>过去查询</strong>的充分统计。生成方向一转，H2 集合可能完全不对。图示任务里，关键证据在中间一句，要等很后面的查询才变得高分。驱逐系统在中间阶段就会把它当低分清掉。QUEST 把稀疏性写成 \\(q\\) 的函数：每步的可见集 \\(S(q_t)\\) 可以和 \\(S(q_{t-1})\\) 不同，旧页随时可以再次被选中。</p><p><span class="marginnote">QUEST 省的是注意力的内存流量，不是显存占用。全部 KV 仍驻留（或仍占逻辑容量）。若显存才是瓶颈，仍要驱逐、量化或卸载；QUEST 解决的是「缓存已经在卡上，但读它太慢」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>KV 按页管理，页大小与 <a href="/llm/paged-attention">PagedAttention</a> 一类块可以同量级。对每一页、每一通道，维护该页内键的最小值与最大值：</p> \\[k_{p,d}^{\\min}=\\min_{j\\in\\mathrm{page}\\ p}K_{j,d},\\qquad k_{p,d}^{\\max}=\\max_{j\\in\\mathrm{page}\\ p}K_{j,d}. \\]<p>当前查询 \\(q\\) 对页 \\(p\\) 的临界性上界取逐通道可能的最大点积再求和：</p> \\[\\hat s_p=\\sum_d \\max\\bigl(q_d k_{p,d}^{\\min},\\, q_d k_{p,d}^{\\max}\\bigr). \\]<p>因为 \\(k_d\\) 落在 \\([k^{\\min}_d,k^{\\max}_d]\\) 时，\\(q_d k_d\\) 的最大值必在端点。\\(\\hat s_p\\) 高表示这一页至少有一个键可能打出高分。选出 Top-\\(K\\) 页（\\(K\\) 如 128、256 页，或换算成 token 预算），只加载这些页的 \\(K,V\\) 做近似 <a href="/llm/sdpa">SDPA</a>。最近页通常强制包含，以免局部句法丢失。元数据是每页每通道两个标量，相对整页 KV 很小。</p><p><span class="marginnote">直觉类比：min/max 像给每页 KV 套一个快递箱外框——不逐件开箱，只量箱子的最长边，就能便宜地估计「这箱对当前包裹单有多大可能相关」，再决定哪几箱值得搬下货架。</span></p><h3 id="层间稀疏度不均" tabindex="-1">层间稀疏度不均 <a class="header-anchor" href="#层间稀疏度不均" aria-label="Permalink to &quot;层间稀疏度不均&quot;">​</a></h3><p>作者在 LongChat-7B 上测：在困惑度几乎不升的约束下，前两层可稀疏度很低（不到约 10%），其余层可超过约 90%。QUEST 的估计与 oracle（若已知该看哪些 token）接近。实现上应对浅层用更大的 \\(K\\) 或关掉稀疏，避免在还没形成特征的层上砍上下文。这不是超参游戏，而是注意力在深度上的经验结构。</p>',18)),(t(),s(l,null,{default:E(()=>[i(o,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20KV%5B%22%E5%AE%8C%E6%95%B4%20KV%20%E6%8C%89%E9%A1%B5%E9%A9%BB%E7%95%99%22%5D%20--%3E%20MM%5B%22%E7%BB%B4%E6%8A%A4%E6%AF%8F%E9%A1%B5%E6%AF%8F%E9%80%9A%E9%81%93%20min%2Fmax%22%5D%0A%20%20Q%5B%22%E5%BD%93%E5%89%8D%20Query%22%5D%20--%3E%20SC%5B%22%E7%94%A8%E7%AB%AF%E7%82%B9%E7%82%B9%E7%A7%AF%E4%BC%B0%E8%AE%A1%E9%A1%B5%E5%88%86%E6%95%B0%22%5D%0A%20%20MM%20--%3E%20SC%0A%20%20SC%20--%3E%20TOP%5B%22%E9%80%89%E5%87%BA%20Top-K%20%E9%A1%B5%22%5D%0A%20%20TOP%20--%3E%20ATT%5B%22%E5%8F%AA%E5%8A%A0%E8%BD%BD%E8%BF%99%E4%BA%9B%E9%A1%B5%E5%81%9A%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20ATT%20--%3E%20OUT%5B%22%E5%86%99%E5%85%A5%E6%96%B0%20KV%20%E5%B9%B6%E6%9B%B4%E6%96%B0%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"机制是「用键的轴对齐包围盒，对当前 \\(q\\) 做一次便宜的上界打分，再把带宽花在上界高的页上」。它不要求物化完整注意力矩阵，也不依赖历史 softmax——因此与 FlashAttention / FlashInfer 的「不输出权重」不冲突：历史分数路径需要的统计，QUEST 根本不需要。估计是页级的，假阳性（页里其实没有真高分 token）只会浪费一次加载；假阴性（真正的针所在页分数偏低）才会伤任务。min/max 在通道异常值上会撑开包围盒，使页分数偏高、Top-\\(K\\) 变「什么都有点像」，稀疏收益下降。这是为了召回付出的精度。",-1)),a[5]||(a[5]=e("p",null,"相对通道剪枝的 SparQ 一类方法，QUEST 保持页内全通道，硬件上仍是规整的块读取。相对驱逐，正确性论证变成「每步近似，但信息仍在」：将来的 \\(q\\) 仍能把漏掉的页再捞回来，只要这一步的 Top-\\(K\\) 没漏掉当前真正需要的证据。",-1)),(t(),s(l,null,{default:E(()=>[i(o,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20EST%5B%22min%2Fmax%20%E5%8C%85%E5%9B%B4%E7%9B%92%E6%89%93%E5%88%86%22%5D%20--%3E%20FP%5B%22%E5%81%87%E9%98%B3%E6%80%A7%EF%BC%9A%E9%A1%B5%E9%87%8C%E5%85%B6%E5%AE%9E%E6%B2%A1%E6%9C%89%E9%AB%98%E5%88%86%E9%94%AE%22%5D%0A%20%20FP%20--%3E%20C1%5B%22%E5%8F%AA%E5%A4%9A%E5%8A%A0%E8%BD%BD%E4%B8%80%E9%A1%B5%EF%BC%8C%E6%B5%AA%E8%B4%B9%E5%B8%A6%E5%AE%BD%22%5D%0A%20%20C1%20--%3E%20OK%5B%22%E4%BC%A4%E9%80%9F%E5%BA%A6%EF%BC%8C%E4%B8%8D%E4%BC%A4%E6%AD%A3%E7%A1%AE%E6%80%A7%22%5D%0A%20%20EST%20--%3E%20FN%5B%22%E5%81%87%E9%98%B4%E6%80%A7%EF%BC%9A%E7%9C%9F%E8%AF%81%E6%8D%AE%E9%A1%B5%E5%88%86%E6%95%B0%E5%81%8F%E4%BD%8E%22%5D%0A%20%20FN%20--%3E%20C2%5B%22%E6%B2%A1%E8%BF%9B%20Top-K%EF%BC%8C%E9%92%88%E8%A2%AB%E8%B7%B3%E8%BF%87%22%5D%0A%20%20C2%20--%3E%20FIX%5B%22K%20%E7%95%99%E4%BD%99%E9%87%8F%EF%BC%8C%E7%94%A8%E9%92%88%E6%A3%80%E7%B4%A2%E5%9B%9E%E5%BD%92%E6%8A%8A%E5%85%B3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">\\(\\hat s_p\\) 是上界启发式，不是该页最大 \\(q^\\top k\\) 的精确值——精确值要看完全页的键。通道求和还会把「许多中等通道」加出高分。\\(K\\) 必须留余量，用针检索回归，而不是只看平均困惑度。</span></p><h3 id="论文数字" tabindex="-1">论文数字 <a class="header-anchor" href="#论文数字" aria-label="Permalink to &quot;论文数字&quot;">​</a></h3><p>32K 上下文上，相对 FlashInfer 的自注意力延迟最高约 7.03× 降低；端到端在 4-bit 权重量化设定下约 2.23×。LongBench、passkey、PG19 上，同等 token 预算比历史驱逐基线更稳。端到端加速小于注意力核加速，因为 FFN 与残差不稀疏。权重量化与 QUEST 正交：一个减权重流量，一个减 KV 流量。</p><p><span class="marginnote">数字实例：Llama 7B 在 32K、FP16 下 KV 约 16GB；只加载八分之一的页，单步搬运就降到约 2GB。省的是每步的 HBM 读取，显存里那 16GB 一字未动——这是「注意力 7×、端到端只有约 2×」的来源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>显存不够时 QUEST 不能单独救命，需要与量化、卸载或真正的驱逐合用；合用后「再捞回来」的能力取决于页是否还在。预填充阶段若也做页选择，会改变首 token 质量，原文主打 decode。页太大，min/max 过粗；页太小，元数据与 Top-\\(K\\) 排序开销涨。排序本身是每步每层一次小操作，通常可忽略，但在极短上下文上 QUEST 可能负加速——没有足够「可跳过的页」。</p><p>不要把 QUEST 写成「稀疏注意力训练法」。模型仍按稠密注意力训练，推理才跳页，是近似。安全过滤、引用要求「必须看见某段原文」时，近似可见集不够格。多请求连续批处理里，每条请求的 \\(q\\) 不同，页选择不能共享；共享的是物理 KV 池，不是 Top-\\(K\\) 集合。</p><p><span class="marginnote">常见误区：把 QUEST 报成「KV 显存省八分之七」。它省的是每步读取流量，全部缓存仍在卡上；显存不够时还得靠量化、卸载或驱逐，两者解决的问题不同。</span></p><p><span class="marginnote">强制包含最近页、并对前几层禁用稀疏，几乎是落地必选项。关掉这两条，只看论文平均稀疏度，会在局部语法和底层表示上先坏掉。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>QUEST 保留全部 KV，按当前查询用页内键的 min/max 估计临界性，只加载 Top-\\(K\\) 页做注意力。</li><li>查询相关稀疏避免历史驱逐的不可逆误杀，适合长依赖与针检索。</li><li>它减的是 HBM 流量而非显存容量；浅层应更密。</li><li>论文：注意力最高约 7.03×，端到端约 2.23×（含权重量化设定）。</li><li>包围盒估计偏召回；页大小、强制最近页与层策略决定质量。</li><li>出处：Tang et al., <em>QUEST: Query-Aware Sparsity for Efficient Long-Context LLM Inference</em>，ICML 2024；arXiv:2406.10774。</li></ul>',11))])}const c=B(d,[["render",m]]);export{q as __pageData,c as default};
